package dev.voltip.mobile

import android.Manifest
import android.app.Activity
import app.tauri.annotation.Permission
import app.tauri.annotation.TauriPlugin
import app.tauri.plugin.Plugin

/**
 * Owns the RECORD_AUDIO runtime permission for the phone as microphone (docs/dictation.md §20).
 * The Rust side (`src/microphone.rs`) calls the base class's `checkPermissions` /
 * `requestPermissions` with the alias `microphone`; capture itself is cpal (AAudio) in Rust.
 * Not generated by `cargo tauri android init`: keep this file when regenerating the project.
 */
@TauriPlugin(
    permissions = [
        Permission(strings = [Manifest.permission.RECORD_AUDIO], alias = "microphone")
    ]
)
class MicrophonePlugin(private val activity: Activity) : Plugin(activity)
